// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.orchestratorimport com.roshan.persona.brain.agentic.ConstitutionalGuardrailsimport com.roshan.persona.brain.agentic.GuardrailResultimport com.roshan.persona.brain.context.BrainBudgetimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.context.DeviceContextimport com.roshan.persona.brain.context.SessionIdimport com.roshan.persona.brain.context.ThermalStatusimport com.roshan.persona.brain.context.UserContextimport com.roshan.persona.brain.llm.context.ContextInjectorimport com.roshan.persona.brain.memory.MemoryInterfaceimport com.roshan.persona.brain.persona.Personaimport com.roshan.persona.common.CorrelationIdimport timber.log.Timberimport java.time.Instantimport java.util.Localeimport java.util.TimeZoneimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Brain Pre-Processor. * * First stage of the brain pipeline. Takes raw user input + session state and * produces a fully-prepared [BrainContext] ready for the 6-layer cascade. * * ## Responsibilities * *   1. **Input normalization** — trim, collapse whitespace, fix encoding *   2. **Banned pattern check** — instant reject for harmful input (before L0) *   3. **Command prefix parsing** — `!local`, `!cloud`, `!agent`, `!rule` force specific layer *   4. **PII scrubbing** — redact phone/email/Aadhaar before cloud calls *   5. **Persona injection** — set active persona (LLM prompt injection happens in ContextInjector) *   6. **Conversation history** — load last N turns from session *   7. **Budget setup** — combine user prefs + device state into per-request [BrainBudget] *   8. **Context assembly** — build [BrainContext] with all metadata * * ## Why Pre-Process? * * Without pre-processing, every layer would repeat the same work (normalization, * PII scrub, history lookup). Centralizing it: *   - Reduces code duplication *   - Ensures consistency (all layers see the same prepared context) *   - Enables early rejection (banned patterns never reach L0) *   - Simplifies layer implementations (they just consume [BrainContext]) * * @see <a href="docs/spec/module2-spec-review.pdf">§10.1 Pre-Processor</a> */@Singletonclass BrainPreProcessor @Inject constructor(    private val memoryInterface: MemoryInterface?,    private val constitutionalGuardrails: ConstitutionalGuardrails,    private val contextInjector: ContextInjector?,) {    /**     * Process raw [userInput] and produce a [PreProcessResult].     *     * @param userInput raw user input (voice-transcribed or typed)     * @param sessionId conversation session     * @param activePersona currently active persona     * @param userContext user identity + preferences     * @param deviceContext device state (thermal, RAM, battery, network)     * @param preferredTimezone user's timezone (for time-aware rules)     * @return [PreProcessResult] with either prepared context or rejection     */    suspend fun process(        userInput: String,        sessionId: SessionId,        activePersona: Persona,        userContext: UserContext,        deviceContext: DeviceContext,        preferredTimezone: TimeZone = TimeZone.getDefault(),    ): PreProcessResult {        val correlationId = CorrelationId.generate()        val startNanos = System.nanoTime()        // ─── 1. Normalize input ───────────────────────────────────────────        val normalized = normalizeInput(userInput)        if (normalized.isBlank()) {            return PreProcessResult.Rejected(                correlationId = correlationId,                reason = "Input is empty after normalization",                category = RejectionCategory.EMPTY_INPUT,            )        }        // ─── 2. Banned pattern check (early safety) ───────────────────────        val bannedCheck = constitutionalGuardrails.checkInput(normalized)        if (bannedCheck is GuardrailResult.Blocked) {            Timber.tag("NOUS.Pre").w("Input banned: %s", bannedCheck.reason)            return PreProcessResult.Rejected(                correlationId = correlationId,                reason = bannedCheck.reason,                category = RejectionCategory.BANNED_INPUT,            )        }        // ─── 3. Command prefix parsing ────────────────────────────────────        val (cleanInput, commandOverride) = parseCommandPrefix(normalized)        // ─── 4. PII scrubbing (for cloud — local sees raw) ────────────────        // PII scrubbing happens in CloudLlmLayer via ContextInjector.scrubForCloud        // Pre-processor just marks that PII was detected (for audit log)        val piiDetected = detectPii(cleanInput)        // ─── 5. Conversation history (last N turns) ───────────────────────        val history = loadHistory(sessionId)        // ─── 6. Budget setup ──────────────────────────────────────────────        val budget = computeBudget(userContext, deviceContext, commandOverride)        // ─── 7. Build BrainContext ────────────────────────────────────────        val context = BrainContext(            correlationId = correlationId,            sessionId = sessionId,            timestamp = Instant.now(),            timezone = preferredTimezone,            activePersona = activePersona,            userContext = userContext,            deviceContext = deviceContext,            conversationHistory = history,            pendingExpectation = null,  // Loaded from ConversationStateStorage (Step 2.8 wiring)            ambientContext = null,  // Loaded from AmbientSnapshot (future module)            budget = budget,        )        val durationMs = (System.nanoTime() - startNanos) / 1_000_000        Timber.tag("NOUS.Pre").v(            "Pre-processed in %dms (pii=%s, override=%s, history=%d turns)",            durationMs, piiDetected, commandOverride, history.size,        )        return PreProcessResult.Success(            correlationId = correlationId,            context = context,            cleanInput = cleanInput,            commandOverride = commandOverride,            piiDetected = piiDetected,            durationMs = durationMs,        )    }    // ─── Internal helpers ────────────────────────────────────────────────    /**     * Normalize user input:     *   - Trim leading/trailing whitespace     *   - Collapse multiple spaces/tabs into single space     *   - Normalize Unicode (NFC)     *   - Strip zero-width characters (anti-injection)     */    private fun normalizeInput(input: String): String {        return input            .trim()            .replace(Regex("[\\s\\t]+"), " ")            .normalizeUnicode()            .replace(Regex("[\\u200B\\u200C\\u200D\\uFEFF]"), "")  // zero-width chars    }    private fun String.normalizeUnicode(): String = java.text.Normalizer.normalize(this, java.text.Normalizer.Form.NFC)    /**     * Parse command prefix (!local, !cloud, !agent, !rule).     *     * Returns the cleaned input (prefix removed) and the override (null if no prefix).     */    private fun parseCommandPrefix(input: String): Pair<String, CommandOverride?> {        val trimmed = input.trim()        // Match: !prefix rest OR !prefix: rest        // Supported: !local, !cloud, !agent, !rule (layer forcing)        //           !openai, !anthropic, !gemini, !groq, !openrouter (provider forcing)        val match = Regex(            "^!(local|cloud|agent|rule|openai|anthropic|gemini|groq|openrouter)[:\\s]+(.+)$",            RegexOption.IGNORE_CASE,        ).matchEntire(trimmed)            ?: return input to null        val prefix = match.groupValues[1].lowercase()        val rest = match.groupValues[2].trim()        val override = when (prefix) {            "local" -> CommandOverride.FORCE_LOCAL            "cloud" -> CommandOverride.FORCE_CLOUD            "agent" -> CommandOverride.FORCE_AGENT            "rule" -> CommandOverride.FORCE_RULE            "openai" -> CommandOverride.FORCE_CLOUD_PROVIDER("openai")            "anthropic" -> CommandOverride.FORCE_CLOUD_PROVIDER("anthropic")            "gemini" -> CommandOverride.FORCE_CLOUD_PROVIDER("gemini")            "groq" -> CommandOverride.FORCE_CLOUD_PROVIDER("groq")            "openrouter" -> CommandOverride.FORCE_CLOUD_PROVIDER("openrouter")            else -> null        }        return rest to override    }    /**     * Detect PII in input (for audit log — actual scrubbing happens in CloudLlmLayer).     */    private fun detectPii(input: String): Boolean {        for ((pattern, _) in ContextInjector.PII_PATTERNS) {            if (pattern.containsMatchIn(input)) return true        }        return false    }    /**     * Load conversation history (last N turns).     *     * Real impl reads from Room (conversation_turns table) in Module 3.     * For Module 2, returns empty list (history loaded externally).     */    private suspend fun loadHistory(sessionId: SessionId): List<com.roshan.persona.brain.context.Turn> {        // In Module 3, this will query Room via ConversationStateStorage        return emptyList()    }    /**     * Compute per-request budget based on:     *   - User's monthly LLM budget (default $5)     *   - Device state (thermal, battery → may reduce budget)     *   - Command override (force_local → no cloud budget)     */    private fun computeBudget(        userContext: UserContext,        device: DeviceContext,        override: CommandOverride?,    ): BrainBudget {        var budget = BrainBudget.DEFAULT        // Reduce budget if device is hot        if (device.thermalStatus.isAtLeast(ThermalStatus.SEVERE)) {            budget = budget.copy(maxLatencyMs = 2_000L, allowCloud = false)        }        // Reduce budget if battery critical        if (device.batteryLevel < 15 && !device.isCharging) {            budget = budget.copy(allowCloud = false, allowAgentic = false)        }        // If cloud is disabled in privacy settings, force local-only        if (!userContext.privacySettings.cloudLlmEnabled) {            budget = budget.copy(allowCloud = false)        }        // Apply command override        when (override) {            is CommandOverride.FORCE_LOCAL -> budget = budget.copy(allowCloud = false)            is CommandOverride.FORCE_CLOUD -> budget = budget.copy(allowCloud = true)            is CommandOverride.FORCE_AGENT -> budget = budget.copy(allowAgentic = true)            is CommandOverride.FORCE_RULE -> budget = budget.copy(allowAgentic = false, allowCloud = false)            is CommandOverride.FORCE_CLOUD_PROVIDER -> budget = budget.copy(allowCloud = true)            null -> { /* no override */ }        }        return budget    }}/** * Result of pre-processing. */sealed interface PreProcessResult {    /** Correlation ID assigned to this request. */    val correlationId: CorrelationId    /**     * Pre-processing succeeded — context is ready for the layer cascade.     */    data class Success(        override val correlationId: CorrelationId,        /** Fully-prepared brain context. */        val context: BrainContext,        /** Cleaned user input (normalized, prefix removed). */        val cleanInput: String,        /** Command override (!local, !cloud, etc.) — null if no override. */        val commandOverride: CommandOverride?,        /** Whether PII was detected in input. */        val piiDetected: Boolean,        /** Pre-processing duration in milliseconds. */        val durationMs: Long,    ) : PreProcessResult    /**     * Pre-processing rejected the input (banned pattern, empty, etc.).     */    data class Rejected(        override val correlationId: CorrelationId,        /** Why it was rejected. */        val reason: String,        /** Category of rejection (for audit log). */        val category: RejectionCategory,    ) : PreProcessResult}/** * Command override — forces a specific layer (debug/power-user feature). * * Sealed class (not enum) so we can carry the `providerId` payload for * `FORCE_CLOUD_PROVIDER` (e.g., `!openai`, `!anthropic`). */sealed class CommandOverride {    /** Force local LLM only (!local). */    object FORCE_LOCAL : CommandOverride()    /** Force cloud LLM only (!cloud). */    object FORCE_CLOUD : CommandOverride()    /** Force agentic orchestrator (!agent). */    object FORCE_AGENT : CommandOverride()    /** Force rule engine only (!rule). */    object FORCE_RULE : CommandOverride()    /**     * Force a specific cloud provider by id (!openai, !anthropic, !gemini, !groq, !openrouter).     *     * The providerId must match a registered CloudLlmProvider's `providerId`.     * BrainOrchestrator will skip layers 0-3 and route directly to CloudLlmLayer     * with this provider selected.     */    data class FORCE_CLOUD_PROVIDER(val providerId: String) : CommandOverride()}/** * Why pre-processing rejected the input. */enum class RejectionCategory {    /** Input was empty after normalization. */    EMPTY_INPUT,    /** Input matched a banned pattern (harmful/jailbreak). */    BANNED_INPUT,    /** Input exceeded max length. */    TOO_LONG,}